import{z as n,x as l,o as r,c as p,q as i,j as B,D as E,d as t,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"固件：BIOS 与 UEFI","description":"","frontmatter":{"title":"固件：BIOS 与 UEFI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bios-uefi.md","filePath":"cs/bios-uefi.md","lastUpdated":1791063341000}'),d={name:"cs/bios-uefi.md"};function I(S,a,F,c,C,f){const s=l("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="固件-bios-与-uefi" tabindex="-1">固件：BIOS 与 UEFI <a class="header-anchor" href="#固件-bios-与-uefi" aria-label="Permalink to &quot;固件：BIOS 与 UEFI&quot;">​</a></h1><div class="epigraph"><p>复位后最先跑的不是内核：固件在 SPI 闪存里，训练 DRAM、枚举 PCIe、提供启动服务，再把控制交给引导加载器。</p><footer>—— 据 UEFI Specification；Intel, PCI Firmware Specification 实践；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/framebuffer-display">上一课</a>的 GOP 由固件提供。<a href="/cs/early-boot">早期启动</a>从引导加载器之后讲内核。缺口是更早的 <strong>BIOS/UEFI</strong>：CPU 复位向量指向只执行闪存，如何变成「有 DRAM、有设备、能读盘」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复位：<a href="/cs/reset-strategy">复位策略</a>后 PC 在复位向量（x86 在高地址别名）。此时 DRAM 未训练，只能用 SRAM/Cache-as-RAM。固件：FSP/AGC 一类训练 <a href="/cs/ddr-protocol">DDR</a>，按 <a href="/cs/pcie-tlp-bar">BAR</a> 枚举，用 <a href="/cs/i2c-spi-uart">SPI</a> 读自己，安装 UEFI 启动服务（磁盘、GOP、时间）。传统 BIOS 用 16 位中断调用；UEFI 用表与协议。缺口不是内核 <code>start_kernel</code>，而是这条<strong>硅启动链</strong>。</p><p><span class="marginnote">直觉类比：复位后的 CPU 像刚睡醒的人——手边还没有桌子（DRAM 没训练好），只能把便签贴在自己身上（拿 CPU 缓存当 SRAM 用，即 Cache-as-RAM），先收拾利索，才有地方放后面的大行李。</span></p><p>Secure Boot：用密钥验引导加载器，点名，安全课再深。ACPI 表描述 APIC、HPET、NUMA，交给 OS。</p><h3 id="uefi-不是操作系统" tabindex="-1">UEFI 不是操作系统 <a class="header-anchor" href="#uefi-不是操作系统" aria-label="Permalink to &quot;UEFI 不是操作系统&quot;">​</a></h3><p>退出启动服务后多数固件驱动消失，运行时服务子集留下（变量、时间）。把 UEFI 当小型 Linux，设备驱动模型会错。BIOS 调用在长模式下不可用，故现代 OS 依赖 UEFI/ACPI 或设备树。</p><p><span class="marginnote">常见误区：以为固件一直在后台干活。多数固件驱动在 ExitBootServices 之后就交还资源消失了，只留变量、时间等一小撮运行时服务；把它当成常驻的小型操作系统，设备模型会全错。</span></p><p><span class="marginnote">UEFI 规范是主文献。PCI Firmware Spec 讲枚举。Patterson/Hennessy 的复位启动在 x86 上具体化为本课。核心启动（coreboot）是另一实现，合同类似。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SEC/PEI：CAR、内存训练。DXE：驱动、协议。BDS：启动策略、选盘、链加载。SMM：高特权运行时黑洞，本课承认存在。RISC-V：OpenSBI/BOOTROM 扮演类似角色，无 16 位 BIOS。</p>',13)),(r(),B(A,null,{default:E(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RST%5B%22%E5%A4%8D%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%20--%3E%20CAR%5B%22%E6%97%A0%20DRAM%20%E9%98%B6%E6%AE%B5%22%5D%0A%20%20CAR%20--%3E%20MEM%5B%22DDR%20%E8%AE%AD%E7%BB%83%22%5D%0A%20%20MEM%20--%3E%20ENUM%5B%22PCIe%20%2F%20USB%20%E6%9E%9A%E4%B8%BE%22%5D%0A%20%20ENUM%20--%3E%20BOOT%5B%22%E5%90%AF%E5%8A%A8%E6%9C%8D%E5%8A%A1%20%E2%86%92%20%E5%8A%A0%E8%BD%BD%E5%99%A8%22%5D%0A%20%20BOOT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AISA%20%E5%AF%B9%E7%85%A7%E4%BB%8E%20x86%20%E7%BC%96%E7%A0%81%E5%BC%80%E5%A7%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"内存与 I/O 单元到此：从 bank 到固件把接口交给软件。下一单元对照 x86/ARM/RISC-V 的指令与 ABI 边界。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"OS 接手后仍通过 ACPI/UEFI 运行时改启动项、读变量。DMA 与 IOMMU 常在 OS 里才开，固件阶段需谨慎。本课封上 I/O 课序：协议与启动已经能接到内核课已有的早期启动。",-1)),a[6]||(a[6]=e("p",null,"ExitBootServices 前后，固件各留下什么：",-1)),(r(),B(A,null,{default:E(()=>[o(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20BS%5B%22%E5%90%AF%E5%8A%A8%E6%9C%8D%E5%8A%A1%EF%BC%9A%E7%A3%81%E7%9B%98%E3%80%81GOP%E3%80%81%E6%80%BB%E7%BA%BF%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20EBS%5B%22OS%20%E8%B0%83%E7%94%A8%20ExitBootServices%22%5D%0A%20%20EBS%20--%3E%20GONE%5B%22%E5%A4%9A%E6%95%B0%E5%9B%BA%E4%BB%B6%E9%A9%B1%E5%8A%A8%E4%BA%A4%E8%BF%98%E8%B5%84%E6%BA%90%E6%B6%88%E5%A4%B1%22%5D%0A%20%20EBS%20--%3E%20OS%5B%22%E5%86%85%E6%A0%B8%E5%BC%80%E5%A7%8B%E6%8E%A5%E7%AE%A1%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20OS%20--%3E%20RT%5B%22%E7%95%99%E4%B8%8B%EF%BC%9AUEFI%20%E8%BF%90%E8%A1%8C%E6%97%B6%E6%9C%8D%E5%8A%A1%EF%BC%88%E5%8F%98%E9%87%8F%E3%80%81%E6%97%B6%E9%97%B4%EF%BC%89%22%5D%0A%20%20OS%20--%3E%20TBL%5B%22%E7%95%99%E4%B8%8B%EF%BC%9AACPI%20%E8%A1%A8%E6%8F%8F%E8%BF%B0%E5%B9%B3%E5%8F%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">数字实例：x86 复位后首条指令取自线性地址 0xFFFFFFF0——4 GB 末尾往下 16 字节处，那里映射的是 SPI 闪存而非 RAM。所谓「开机第一课」，物理上发生在闪存芯片里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CSM 兼容细节全书，不把 ME/PSP 固件引擎当主体。不讨论刷机变砖流程。不进入许可密钥。</p><p>后课默认：复位后固件训练内存并枚举 PCIe；UEFI 启动服务把内核装进来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固件先于内核：训练 DRAM、枚举、启动服务。</li><li>BIOS 中断 vs UEFI 协议；ACPI 描述平台。</li><li>I/O 单元收束；下一课 x86-64 编码。</li><li>出处：UEFI Specification；PCI Firmware Spec；Patterson and Hennessy, COD。</li></ul>',6))])}const u=n(d,[["render",I]]);export{D as __pageData,u as default};
